// @ts-nocheck
// #region 6. FORMAT & COLOR UTILS
import { THREE } from "../core/deps.tsx"

export function detectFormat(url) {
    if (!url) return null
    const ext = url.split("?")[0].split("#")[0].toLowerCase().split(".").pop()
    if (ext === "glb" || ext === "gltf") return ext
    if (ext === "fbx") return "fbx"
    if (ext === "zip") return "zip"
    return null // Only GLB/GLTF/FBX/ZIP supported — other formats should be converted in Blender
}

export function detectImageFormat(url) {
    if (!url) return null
    const ext = url.split("?")[0].split("#")[0].toLowerCase().split(".").pop()
    if (
        ext === "png" ||
        ext === "jpg" ||
        ext === "jpeg" ||
        ext === "webp" ||
        ext === "avif"
    ) {
        return ext
    }
    return null
}

export function _normalizeLayerMatchValue(value) {
    return String(value ?? "")
        .trim()
        .toLowerCase()
}

function _normalizeExactLayerMatchValue(value) {
    return String(value ?? "")
        .trim()
        .replace(/^[#.]/, "")
}

export function _getLayerMatchValues(node) {
    if (!node) return []
    const values = [
        node.id,
        node.getAttribute?.("aria-label"),
        node.getAttribute?.("data-framer-name"),
        node.getAttribute?.("data-framer-component-name"),
        node.getAttribute?.("data-section-id"),
        node.getAttribute?.("data-name"),
        node.getAttribute?.("title"),
    ]
    if (node.classList) values.push(...Array.from(node.classList))
    return values
        .filter(Boolean)
        .map((value) => _normalizeLayerMatchValue(value))
}

export function _getLayerMatchScore(node, targets) {
    if (!node || !targets?.length) return 0
    const targetSet = new Set(targets)
    const sectionId = _normalizeLayerMatchValue(
        node.getAttribute?.("data-section-id")
    )
    if (sectionId && targetSet.has(sectionId)) {
        return 300
    }
    const id = _normalizeLayerMatchValue(node.id)
    if (id && targetSet.has(id)) {
        return 200
    }
    return 0
}

export function _getLayerMatchArea(node) {
    const rect = node?.getBoundingClientRect?.()
    if (!rect) return 0
    return Math.max(0, rect.width) * Math.max(0, rect.height)
}

export function _resolveScrollAnchorY(value: any, fallback = 0.5) {
    if (typeof value === "number" && Number.isFinite(value)) {
        return Math.max(0, Math.min(1, value))
    }
    const key = String(value ?? "")
        .trim()
        .toLowerCase()
    if (key === "top" || key === "start") return 0
    if (key === "bottom" || key === "end") return 1
    if (key === "middle" || key === "mid" || key === "center") return 0.5
    return fallback
}

export function _getObjectEventScrollProgress(
    selector,
    wrapNode = null,
    anchor = 0.5
) {
    if (typeof window === "undefined") return 1
    const match = String(selector ?? "").trim()
    if (!match) return 1
    const el = _findLayerMatchElement(match, wrapNode)
    if (!el) return 0
    const rect = el.getBoundingClientRect?.()
    const viewH = window.innerHeight || 1
    if (!rect || !viewH) return 0
    const anchorY = rect.top + rect.height * _resolveScrollAnchorY(anchor)
    return Math.max(0, Math.min(1, 1 - anchorY / viewH))
}

export function _isLayerMatchCandidateUsable(node, wrapNode) {
    if (!node || node.nodeType !== 1) return false
    if (wrapNode && wrapNode.contains?.(node)) return false
    if (node.getAttribute?.("data-3d-canvas-id")) return false
    const rect = node.getBoundingClientRect?.()
    // Framer can scale an ID target to a fractional CSS-pixel size (for
    // example, 0.998px high). It is still a real visible target and must not
    // be rejected, or Scroll ID resolution will vary with browser zoom/scaling.
    if (!rect || rect.width <= 0 || rect.height <= 0) return false

    let current = node
    while (current && current !== document.body) {
        if (
            current.getAttribute?.("aria-hidden") === "true" ||
            current.getAttribute?.("data-framer-hidden") === "true"
        ) {
            return false
        }

        const style =
            typeof window !== "undefined"
                ? window.getComputedStyle(current)
                : null
        if (
            style &&
            (style.display === "none" ||
                style.visibility === "hidden" ||
                Number(style.opacity) === 0)
        ) {
            return false
        }
        current = current.parentElement
    }
    return true
}

export function _matchesLayerSelector(rootNode, selector) {
    const targets = String(selector ?? "")
        .split(",")
        .map(_normalizeLayerMatchValue)
        .flatMap((value) => [value, value.replace(/^[#.]/, "")])
        .filter(Boolean)
    if (!targets.length) return true

    let node = rootNode
    while (node && node !== document.body) {
        const values = _getLayerMatchValues(node)
        for (const target of targets) {
            if (values.some((value) => value === target)) return true
        }
        node = node.parentElement
    }
    return false
}

export function _findLayerMatchElement(selector, wrapNode = null) {
    if (typeof document === "undefined") return null
    const targets = String(selector ?? "")
        .split(",")
        .map(_normalizeExactLayerMatchValue)
        .filter(Boolean)
    if (!targets.length) return null

    const exactCandidates = document.querySelectorAll("[data-section-id],[id]")
    const usableCandidates = Array.from(exactCandidates).filter((node) =>
        _isLayerMatchCandidateUsable(node, wrapNode)
    )

    // Deterministic resolution for Follow ID:
    // 1. exact HTML id (IDs are case-sensitive)
    // 2. exact Framer section ID
    // 3. a case-insensitive fallback only when it is unambiguous
    for (const target of targets) {
        const exactId = usableCandidates.find((node) => node.id === target)
        if (exactId) return exactId

        const exactSectionId = usableCandidates.find(
            (node) => node.getAttribute?.("data-section-id") === target
        )
        if (exactSectionId) return exactSectionId

        // Keep the historical case-insensitive behavior for unique matches,
        // but do not guess between duplicate IDs that differ only by case.
        const foldedTarget = target.toLowerCase()
        const foldedMatches = usableCandidates.filter((node) => {
            return (
                _normalizeLayerMatchValue(node.id) === foldedTarget ||
                _normalizeLayerMatchValue(
                    node.getAttribute?.("data-section-id")
                ) === foldedTarget
            )
        })
        if (foldedMatches.length === 1) return foldedMatches[0]
    }

    return null
}

export function parseColor(c) {
    if (!c) return new THREE.Color(0x1c1c1c)
    try {
        // Framer's ControlType.Color may return rgba() which THREE.Color doesn't support
        // Strip alpha channel: "rgba(R, G, B, A)" → "rgb(R, G, B)"
        let s = typeof c === "string" ? c.trim() : c

        // Handle CSS variables: "var(--token-xyz, rgb(219, 38, 37))"
        if (typeof s === "string" && s.includes("var(")) {
            // Extract fallback value after comma (if exists)
            const match = s.match(/var\([^,]+,\s*([^)]+)\)/)
            if (match && match[1]) {
                s = match[1].trim()
            } else {
                // No fallback — use default color
                return new THREE.Color(0x1c1c1c)
            }
        }

        if (typeof s === "string" && s.startsWith("rgba(")) {
            const parts = s.slice(5, -1).split(",")
            s = `rgb(${parts[0]},${parts[1]},${parts[2]})`
        }
        return new THREE.Color(s)
    } catch {
        return new THREE.Color(0x1c1c1c)
    }
}
// #endregion
